double Lap(){var value=watch.Elapsed.TotalMilliseconds;watch.Restart();return value;} void Write(string name,object value)=>File.WriteAllText(Path.Combine(output,name),JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true,PropertyNamingPolicy=JsonNamingPolicy.CamelCase,IncludeFields=true}));
static double Mean(IEnumerable<double> values){var a=values.ToArray();return a.Length==0?0:a.Average();} static double Rms(IEnumerable<double> values){var a=values.ToArray();return a.Length==0?0:Math.Sqrt(a.Average(x=>x*x));} static double Max(IEnumerable<double> values)=>values.DefaultIfEmpty(0).Max(); static double P(IEnumerable<double> values,double p){var a=values.Order().ToArray();return a.Length==0?0:a[(int)Math.Clamp(Math.Ceiling(p*a.Length)-1,0,a.Length-1)];}
static IEnumerable<double> GridValues(BilinearScalarField field){for(var i=0;i<field.CountU;i++)for(var j=0;j<field.CountV;j++)yield return field[i,j];} static string Sha(byte[] bytes)=>Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
static string FindRoot(){var directory=new DirectoryInfo(AppContext.BaseDirectory);while(directory is not null&&!File.Exists(Path.Combine(directory.FullName,"Aetheris.slnx")))directory=directory.Parent;return directory?.FullName??Directory.GetCurrentDirectory();}
